11: export function orderHistory () {
12:   return async (req: Request, res: Response, next: NextFunction) => {
13:     const loggedInUser = security.authenticatedUsers.get(req.headers?.authorization?.replace('Bearer ', ''))
14:     if (loggedInUser?.data?.email && loggedInUser.data.id) {
15:       const email = loggedInUser.data.email
16:       const updatedEmail = email.replace(/[aeiou]/gi, '*')
17:       const order = await ordersCollection.find({ email: updatedEmail })
18:       res.status(200).json({ status: 'success', data: order })
19:     } else {
20:       next(new Error('Blocked illegal activity by ' + req.socket.remoteAddress))
21:     }
22:   }
23: }
